        ...
        if (isset($_GET['token']) && $_GET['token'] == 'user_token') {
            if ($user_exists) {
                $query = "SELECT first_name, last_name, user_id, avatar FROM users WHERE user_id = '$id';";
                $result = mysqli_query($GLOBALS["___mysqli_ston"], $query);", "source": "GET 参数 user_id（配合 action 与 token 参数）", "source_kind": "query", "source_name": "user_id", "tainted_expression": "$_GET['user_id'] → $id", "sink": "mysqli_query($GLOBALS["___mysqli_ston"], "SELECT ... WHERE user_id = '$id'")（第 21、28 行）", "endpoint": "/009.php", "http_method": "GET", "exploit_chain": [{"step": 1, "location": "009.php:13", "description": "入口检查 action 与 user_id 参数是否存在", "data_state": "原始 GET 字符串"}, {"step": 2, "location": "009.php:14", "description": "preg_match('/^\d+$/') 仅校验纯数字，未做 SQL 转义", "data_state": "通过校验的纯数字字符串", "bypass_reason": "校验只限制字符集为数字，未阻断后续拼接；且 token 校验为硬编码常量，可被任意满足"}, {"step": 3, "location": "009.php:17", "description": "$id 直接取自 $_GET['user_id']", "data_state": "未转义字符串"}, {"step": 4, "location": "009.php:21", "description": "拼接进 SELECT 语句并执行", "data_state": "进入 SQL 语法"}, {"step": 5, "location": "009.php:26", "description": "token 硬编码为 user_token，攻击者可直接提供", "data_state": "校验通过", "bypass_reason": "token 为固定常量 user_token，无随机性/无会话绑定"}, {"step": 6, "location": "009.php:28", "description": "再次拼接 $id 执行资料查询", "data_state": "进入 SQL 语法"}], "poc": {"description": "利用硬编码 token 与数字型注入点，构造布尔/联合查询探测数据库内容。", "preconditions": ["目标可访问 009.php", "无需登录（脚本未做认证）"], "steps": [{"step": 1, "action": "发送带合法 token 的请求，确认资料查询可达", "request": "GET /009.php?action=view&user_id=1&token=user_token HTTP/1.1
